function decisionMarkdownPaths(paths: readonly string[], requirementsDir: string | undefined): string[] {
  return paths
    .filter(path => isDecisionMarkdownPath(path, { requirementsDir }))
    .sort((a, b) => a.localeCompare(b));
}

