        fix: 'resume with the original prompt only',
      }])}\n`, 'utf8');
      await assert.rejects(
        liveHandlers.cross_host_review({
          storyId: STORY_ID,
          policy: reviewOnlyPolicy(),
          hostAFindingsFile,
          runId: `${STORY_ID}-xhr-live-resume-refusal`,
          managedRunId: liveSubmission.managedRunId,
          json: true,
        }),
