/**
 * A fake seam whose stdout was TRUNCATED at the retained-memory cap (the retained
 * `stdout` is a valid-pass PREFIX; the disqualifying trailing content was dropped).
 * exitCode 0 + timedOut false: the run "completed cleanly" — only truncated=true
 * signals the integrity failure. `honestDigest` (optional) is the sha256 of the TRUE
 * full stream, distinct from sha256 of the retained prefix.
 */
function fakeSeamTruncated(stdout: string, honestDigest?: string): CodexReviewRunner {
  return (): CodexReviewRunnerResult => ({
    stdout,
    exitCode: 0,
    timedOut: false,
    truncated: true,
    ...(honestDigest !== undefined ? { stdoutDigest: honestDigest } : {}),
  });
}

function verdictJsonStdout(materialHash: string, decision: 'pass' | 'fail' | 'blocked', findings: Finding[], summary: string): string {
  const verdict = { schemaVersion: CODEX_REVIEW_VERDICT_SCHEMA, decision, materialHash, findings, summary };
  // Wrap it in transcript noise to prove extraction pulls ONLY the final verdict object.
  return [
    'codex: reading additional input from stdin...',
    '{"type":"tool_log","message":"scanning packages/main/src/index.ts"}',
    'Here is my final verdict:',
    JSON.stringify(verdict, null, 2),
  ].join('\n');
}

function waitForExit(child: ReturnType<typeof spawn>): Promise<number | null> {
  return new Promise((resolve, reject) => {
    child.once('error', reject);
    child.once('close', code => resolve(code));
  });
}

async function xhrWorkerMain(root: string, runId: string, materialHash: string, markerDir: string): Promise<void> {
  mkdirSync(markerDir, { recursive: true });
  const runner: HostRunRunner = async plan => {
    writeFileSync(join(markerDir, `provider-${process.pid}.spawn`), runId, { flag: 'wx', mode: 0o600 });
    await new Promise(resolve => setTimeout(resolve, 400));
    const stdout = verdictJsonStdout(materialHash, 'pass', [], 'detached cross-host worker passed once');
    plan.onChunk?.({ stream: 'stdout', text: stdout });
    return { stdout, stderr: '', exitCode: 0, timedOut: false, terminalReason: 'completed' };
  };
  await runManagedHostRunWorker({ root, runId }, { runner, env: { ...process.env, LATTICE_USAGE_LEDGER: '0' } });
}

async function xhrSubmitterMain(root: string, hostAFindingsFile: string, resultPath: string, markerDir: string): Promise<void> {
  process.chdir(root);
  resetConfigCache();
  const store = new StoryStore(root);
  const materialHash = currentMaterialHash(root, 'HEAD', root)!;
  const launchWorker: ManagedHostRunWorkerLauncher = async request => {
    const child = spawn(process.execPath, [SELF, '--xhr-worker', request.root, request.runId, materialHash, markerDir], {
      cwd: request.root,
      detached: true,
      stdio: 'ignore',
    });
    child.unref();
    return { pid: child.pid ?? 0 };
  };
  const handlers = createCrossHostReviewHandlers({ root, store, scanRoot: join(root, 'packages/main') }, { launchWorker });
  const submission = await handlers.cross_host_review({
    storyId: STORY_ID,
    policy: reviewOnlyPolicy(),
    hostAFindingsFile,
